<aside class="rounded-3xl border border-border bg-white p-5 shadow-sm"><div class="mb-4 flex items-center gap-2"><span class="grid h-9 w-9 place-items-center rounded-xl bg-amber-50 text-lg">👑</span><div><h2 class="font-black">Leaderboard Hari Ini</h2><p class="text-xs text-ink-muted">Finish tercepat & progres terbanyak</p></div></div><div class="space-y-2"><template x-for="(person,index) in leaderboard" :key="person.id"><button @click="selectedStaff=person" class="flex w-full items-center gap-3 rounded-xl border border-border/60 p-2.5 text-left hover:bg-surface-muted"><span class="w-6 text-lg" x-text="['🥇','🥈','🥉'][index]||'#'+(index+1)"></span><img :src="person.avatar" :alt="person.name" x-on:error="$event.target.onerror=null; $event.target.src=person.avatar_fallback" class="h-9 w-9 rounded-full object-cover"><div class="min-w-0 flex-1"><b class="block truncate text-sm" x-text="person.name"></b><span class="text-xs text-ink-muted" x-text="`${person.completed_daily}/${person.total_daily} aktivitas`"></span></div><span class="text-right text-[11px] font-bold text-emerald-600" x-text="person.finish_time?'Finish '+person.finish_time:person.last_activity_at"></span></button></template></div></aside>
